/bin/bash -lc "python - <<'PY'
import json

def walk(xs, prefix=''):
    for x in xs or []:
        name=x.get('name') or '<noname>'
        print(prefix+name, '| type=', x.get('type'), '| label=', x.get('label'), '| value=', x.get('value'))
        if x.get('options'):
            print(prefix+' options:', x['options'][:30] if isinstance(x['options'], list) else x['options'])
        if x.get('cases'):
            for c in x['cases']:
                print(prefix+' CASE', c.get('value'), c.get('label'))
                walk(c.get('inputs'), prefix+'  ')
        if x.get('inputs'):
            walk(x.get('inputs'), prefix+'  ')

for path in ['run_trace/phykit_metrics_tool_schema.json','run_trace/phykit_alignment_tool_schema.json','run_trace/rank_tool_schema.json']:
    print('\\n===', path, '===')
    d=json.load(open(path))
    walk(d.get('inputs'))
PY"

/bin/bash -lc "python - <<'PY'
import json
for path in ['run_trace/phykit_metrics_tool_schema.json','run_trace/rank_tool_schema.json']:
  d=json.load(open(path))
  print('\\n',path)
  def walk(xs, pref=''):
    for x in xs or []:
      print(pref, 'name=',x.get('name'),'type=',x.get('type'),'param=',x.get('name'),'test_param=',x.get('test_param'), 'value=',x.get('value'))
      for key in ['argument','truevalue','falsevalue','checked','optional','multiple']:
        if key in x: print(pref, ' ',key,'=',x[key])
      if 'cases' in x:
        for c in x['cases']:
          print(pref,' CASE value=',c.get('value'),'test_param=',c.get('test_param'),'inputs', [i.get('name') for i in c.get('inputs',[])])
          walk(c.get('inputs'), pref+'   ')
      if x.get('inputs'):
        walk(x['inputs'], pref+'  ')
  walk(d.get('inputs'))
PY"

